CREATE TABLE public.bills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), description text NOT NULL, amount numeric NOT NULL CHECK (amount > 0), kind text NOT NULL DEFAULT 'expense' CHECK (kind IN ('expense','income')), due_on date, reference_month text NOT NULL DEFAULT '', paid boolean NOT NULL DEFAULT false, status_override boolean, account text NOT NULL DEFAULT 'Não informada', source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','notion')), external_id text, source_url text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,external_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.bills TO authenticated; GRANT ALL ON public.bills TO service_role; ALTER TABLE public.bills ENABLE ROW LEVEL SECURITY; CREATE POLICY bills_owner ON public.bills FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE TABLE public.notion_finance_access (user_id uuid PRIMARY KEY, organizer_page_id uuid NOT NULL); GRANT SELECT ON public.notion_finance_access TO authenticated; GRANT ALL ON public.notion_finance_access TO service_role; ALTER TABLE public.notion_finance_access ENABLE ROW LEVEL SECURITY; CREATE POLICY notion_access_owner ON public.notion_finance_access FOR SELECT TO authenticated USING (user_id = auth.uid());